#include <iostream>

void duplicar(int& valor) {
    valor *= 2;          // modifica la variable original
}

int main() {
    int a = 5;
    duplicar(a);
    std::cout << a << '\n'; // 10

    int& alias = a;      // otro nombre para a
    alias += 1;
    std::cout << a << '\n'; // 11

    return 0;
}

#include <iostream>

void escalar(double* datos, int n, double factor) {
    for (int i = 0; i < n; ++i) {
        datos[i] *= factor;
    }
}

double suma(const double* datos, int n) {
    double total = 0.0;
    for (int i = 0; i < n; ++i) {
        total += datos[i];
    }
    return total;
}

int main() {
    const int n = 4;
    double* datos = new double[n]{1.0, 2.0, 3.0, 4.0};

    escalar(datos, n, 0.5);
    std::cout << suma(datos, n) << '\n'; // 5

    delete[] datos;   // new[] exige delete[]
    datos = nullptr;
    return 0;
}

#include <iostream>

int* ampliar(const int* origen, int n, int nuevo_tam) {
    int* nuevo = new int[nuevo_tam]{};   // valor-inicializado a 0
    for (int i = 0; i < n; ++i) {
        nuevo[i] = origen[i];
    }
    return nuevo;
}

int main() {
    int* v = new int[3]{10, 20, 30};
    int* w = ampliar(v, 3, 5);

    delete[] v;      // el bloque antiguo ya no se usa
    v = w;

    std::cout << v[0] << ' ' << v[2] << ' ' << v[4] << '\n'; // 10 30 0

    delete[] v;
    v = nullptr;
    return 0;
}

